import hashlib
import math

class HyperLogLog:
    def __init__(self, p: int = 4, seed: int = 0):
        if p < 4 or p > 16:
            raise ValueError("Precision p must be between 4 and 16")
        self.p = p
        self.m = 1 << p
        self.seed = seed
        self.registers = [0] * self.m
        self.alpha = 0.7213 / (1.0 + 1.079 / self.m)

    def _hash(self, item: str) -> int:
        digest = hashlib.sha256(f"{self.seed}:{item}".encode('utf-8')).digest()
        return int.from_bytes(digest[:8], byteorder='big')

    def add(self, item: str) -> None:
        x = self._hash(item)
        j = x >> (64 - self.p)
        w = x & ((1 << (64 - self.p)) - 1)

        # Count leading zeros in (64 - p) bits
        if w == 0:
            rho = 64 - self.p + 1
        else:
            # format to binary string of width 64 - p
            bin_str = bin(w)[2:].zfill(64 - self.p)
            rho = bin_str.find('1') + 1

        if rho > self.registers[j]:
            self.registers[j] = rho

    def count(self) -> int:
        sum_inv = sum(math.pow(2.0, -reg) for reg in self.registers)
        raw_estimate = (self.alpha * self.m * self.m) / sum_inv

        if raw_estimate <= 2.5 * self.m:
            zero_count = self.registers.count(0)
            if zero_count > 0:
                return round(self.m * math.log(self.m / zero_count))
        return round(raw_estimate)

    def merge(self, other: "HyperLogLog") -> None:
        if self.p != other.p:
            raise ValueError("Cannot merge HyperLogLogs with different precision")
        for i in range(self.m):
            if other.registers[i] > self.registers[i]:
                self.registers[i] = other.registers[i]
